// Scale the authored rubric to the exam slot's points when assembling.
export function scaleRubric(question){if(question.type==='choice')return question;const n=question.rubric.length;const base=Math.floor(question.points/n);return {...question,rubric:question.rubric.map((r,i)=>({...r,score:base+(i<question.points%n?1:0)}))};}
